import { FormEvent, ReactNode, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Activity, ArrowLeft, ArrowUpRight, BookOpen, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Copy, FileCheck2, FileText, FolderOpen, Globe2, LayoutDashboard, LogOut, Menu, Mic, Moon, MoreHorizontal, Plus, Search, Send, ShieldCheck, Sun, Trash2, UsersRound, Volume2, X } from 'lucide-react';
import { Language, translate } from './i18n';

const API = import.meta.env.VITE_API_URL || 'http://localhost:8000/api';
type User = { id: string; email: string; role: 'officer' | 'admin' | 'guest' };
type Doc = { id: string; caseId: string; citizen?: string; service?: string; name: string; kind: string; extractedText: string; reviewStatus: string; reviewNote: string; createdAt: string };
type Source = { id: string; title: string; url: string; type: 'document' | 'knowledge' };
type Message = { id: string; role: 'user' | 'assistant'; content: string; sources?: Source[] };
type CaseItem = { id: string; citizen: string; service: string; district: string; status: string; priority: string; assignedTo: string; source?: string; updatedAt: string; summary: string; documents: Doc[] };
type ActivityEvent = { id: string; actor: string; action: string; resourceId?: string; createdAt: string };
type Knowledge = { id: string; title: string; department: string; sourceUrl: string; content: string; reviewStatus: string; createdAt: string };
type Page = 'dashboard' | 'queue' | 'documents' | 'citizens' | 'knowledge' | 'activity' | 'guide' | 'assistant' | 'case' | 'access';
type StaffRequest = { id: string; fullName: string; email: string; department: string; position: string; reason: string; status: string; reviewNote: string; createdAt: string };
type Tab = 'overview' | 'documents' | 'activity';
const T = (s: string, l: Language) => translate(s, l);
const fmtDate = (s: string) => new Intl.DateTimeFormat('en-IN', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(s));
const initials = (s: string) => (s || '?').split(/\s+/).map((p) => p[0]).slice(0, 2).join('').toUpperCase();

async function authFetch(path: string, init: RequestInit = {}, retry = true): Promise<Response> {
  const headers = new Headers(init.headers);
  if (init.body && !(init.body instanceof FormData) && !headers.has('Content-Type')) headers.set('Content-Type', 'application/json');
  let res = await fetch(`${API}${path}`, { ...init, headers, credentials: 'include' });
  if (res.status === 401 && retry && !path.startsWith('/auth/')) {
    const refreshed = await fetch(`${API}/auth/refresh`, { method: 'POST', credentials: 'include' });
    if (refreshed.ok) return authFetch(path, init, false);
    window.dispatchEvent(new CustomEvent('sama:session-expired'));
  }
  return res;
}
async function jsonApi<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await authFetch(path, init);
  const body = res.status === 204 ? null : await res.json().catch(() => null);
  if (!res.ok) throw new Error(body?.detail || body?.message || `Request failed (${res.status})`);
  return body as T;
}

export default function App() {
  const [user, setUser] = useState<User | null>(null);
  const [booting, setBooting] = useState(true);
  const [page, setPage] = useState<Page>('dashboard');
  const [cases, setCases] = useState<CaseItem[]>([]);
  const [documents, setDocuments] = useState<Doc[]>([]);
  const [citizens, setCitizens] = useState<Array<{ name: string; district: string; cases: number; services: string[]; statuses: string[] }>>([]);
  const [knowledge, setKnowledge] = useState<Knowledge[]>([]);
  const [activity, setActivity] = useState<ActivityEvent[]>([]);
  const [selectedId, setSelectedId] = useState('');
  const [caseTab, setCaseTab] = useState<Tab>('overview');
  const [caseNotes, setCaseNotes] = useState<Array<{ id: string; actor: string; content: string; createdAt: string }>>([]);
  const [caseMessages, setCaseMessages] = useState<Array<{ id: string; senderRole: string; content: string; createdAt: string }>>([]);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState('');
  const [query, setQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('All cases');
  const [sortBy, setSortBy] = useState('updated');
  const [pageNum, setPageNum] = useState(1);
  const [showCreate, setShowCreate] = useState(false);
  const [rowMenu, setRowMenu] = useState('');
  const [notice, setNotice] = useState('');
  const [theme, setTheme] = useState<'light' | 'dark'>(() => localStorage.getItem('sama-theme') === 'dark' ? 'dark' : 'light');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('sama-language') as Language) || 'en');
  const [mobileNav, setMobileNav] = useState(false);
  const [notificationOpen, setNotificationOpen] = useState(false);
  const [openDocument, setOpenDocument] = useState<Doc | null>(null);
  const [apiOnline, setApiOnline] = useState<boolean | null>(null);
  const [loginError, setLoginError] = useState('');
  const [loginBusy, setLoginBusy] = useState(false);
  const [staffRequests, setStaffRequests] = useState<StaffRequest[]>([]);
  const [staffRequestsError, setStaffRequestsError] = useState('');
  const [staffRequestsLoading, setStaffRequestsLoading] = useState(false);
  const selected = cases.find((c) => c.id === selectedId) || null;
  const rowsPerPage = 8;
  const pageText = (s: string) => T(s, language);

  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('sama-theme', theme); }, [theme]);
  useEffect(() => { localStorage.setItem('sama-language', language); }, [language]);
  useEffect(() => {
    const expired = () => { setUser(null); setPage('dashboard'); setNotice('Your session expired. Please sign in again.'); };
    window.addEventListener('sama:session-expired', expired);
    void (async () => {
      try { let res = await fetch(`${API}/auth/me`, { credentials: 'include' }); if (res.status === 401) { const refreshed = await fetch(`${API}/auth/refresh`, { method: 'POST', credentials: 'include' }); if (refreshed.ok) res = await fetch(`${API}/auth/me`, { credentials: 'include' }); } if (res.ok) { const account = await res.json(); if (account.role === 'citizen') window.location.replace('http://localhost:5174'); else setUser(account); } }
      catch {}
      finally { setBooting(false); }
    })();
    return () => window.removeEventListener('sama:session-expired', expired);
  }, []);

  const reload = useCallback(async () => {
    if (!user) return;
    setLoading(true); setLoadError('');
    try {
      const [cs, ds, ci, kn, ac] = await Promise.all([
        jsonApi<CaseItem[]>('/cases'), jsonApi<Doc[]>('/documents'), jsonApi<typeof citizens>('/citizens'), jsonApi<Knowledge[]>('/knowledge'), jsonApi<ActivityEvent[]>('/activity'),
      ]);
      setCases(cs); setDocuments(ds); setCitizens(ci); setKnowledge(kn); setActivity(ac);
      setSelectedId((current) => cs.some((c) => c.id === current) ? current : cs[0]?.id || ''); setApiOnline(true);
    } catch (e) { setLoadError(e instanceof Error ? e.message : 'Could not load workspace data.'); setApiOnline(false); }
    finally { setLoading(false); }
  }, [user]);
  useEffect(() => { void reload(); }, [reload]);
  useEffect(() => {
    if (user?.role !== 'admin' || page !== 'access') return;
    setStaffRequestsError(''); setStaffRequestsLoading(true);
    void jsonApi<StaffRequest[]>('/admin/staff-access-requests').then(setStaffRequests).catch((e) => setStaffRequestsError(e instanceof Error ? e.message : 'Could not load access requests.')).finally(() => setStaffRequestsLoading(false));
  }, [user, page]);
  useEffect(() => {
    const onKeys = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setPage('queue'); document.getElementById('case-search')?.focus(); } if (event.key === 'Escape') { setShowCreate(false); setOpenDocument(null); setRowMenu(''); setMobileNav(false); } };
    window.addEventListener('keydown', onKeys); return () => window.removeEventListener('keydown', onKeys);
  }, []);

  async function signIn(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setLoginBusy(true); setLoginError(''); const form = new FormData(e.currentTarget);
    try {
      const res = await fetch(`${API}/auth/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ email: form.get('email'), password: form.get('password'), rememberMe: form.get('remember') === 'on' }) });
      const data = await res.json(); if (!res.ok) throw new Error(data.detail || 'Sign in failed'); setUser(data); setPage('dashboard');
    } catch (e) { setLoginError(e instanceof Error ? e.message : 'Sign in failed.'); }
    finally { setLoginBusy(false); }
  }
  async function exploreGuest() {
    setLoginBusy(true); setLoginError('');
    try { const res = await fetch(`${API}/auth/guest`, { method: 'POST', credentials: 'include' }); const data = await res.json(); if (!res.ok) throw new Error(data.detail || 'Guest access unavailable'); setUser(data); setPage('dashboard'); }
    catch (e) { setLoginError(e instanceof Error ? e.message : 'Guest access unavailable.'); }
    finally { setLoginBusy(false); }
  }
  async function logout() { try { await fetch(`${API}/auth/logout`, { method: 'POST', credentials: 'include' }); } finally { setUser(null); setCases([]); setPage('dashboard'); } }
  async function reviewStaffRequest(id: string, status: 'Approved' | 'Rejected') {
    const note = window.prompt(status === 'Approved' ? 'Optional approval note' : 'Reason for declining this request');
    if (note === null) return;
    try {
      const result = await jsonApi<{ invitationToken?: string }>('/admin/staff-access-requests/' + id + '/review', { method: 'PATCH', body: JSON.stringify({ status, note }) });
      const requests = await jsonApi<StaffRequest[]>('/admin/staff-access-requests'); setStaffRequests(requests);
      if (result.invitationToken) {
        const request = staffRequests.find((item) => item.id === id);
        const inviteLink = `${window.location.origin}/?invite=${encodeURIComponent(result.invitationToken)}&email=${encodeURIComponent(request?.email || '')}`;
        try { await navigator.clipboard.writeText(inviteLink); toast('Approved. One-time invitation link copied; deliver it through your approved secure channel.'); }
        catch { window.prompt('Copy this one-time invitation link and deliver it through your approved secure channel:', inviteLink); }
      } else toast('Access request declined.');
    } catch (e) { toast(e instanceof Error ? e.message : 'Could not review access request.'); }
  }
  function toast(message: string) { setNotice(message); window.setTimeout(() => setNotice(''), 5000); }

  async function createCase(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); const form = new FormData(e.currentTarget); const body = Object.fromEntries(form.entries());
    try { const c = await jsonApi<CaseItem>('/cases', { method: 'POST', body: JSON.stringify(body) }); await reload(); setSelectedId(c.id); setPage('case'); setCaseTab('overview'); setShowCreate(false); toast(`Created ${c.id}`); }
    catch (e) { toast(e instanceof Error ? e.message : 'Could not create case'); }
  }
  async function patchCase(id: string, path: string, payload: unknown, message: string) {
    try { await jsonApi(`/cases/${id}/${path}`, { method: 'PATCH', body: JSON.stringify(payload) }); await reload(); toast(message); }
    catch (e) { toast(e instanceof Error ? e.message : 'Could not update case'); }
  }
  async function changeStatus(id: string, status: string) { await patchCase(id, 'status', { status }, `Case status saved: ${status}`); }
  async function addNote(id: string) {
    const content = window.prompt('Add a case note'); if (content === null) return; if (!content.trim()) { toast('Enter a note before saving.'); return; }
    try { await jsonApi(`/cases/${id}/notes`, { method: 'POST', body: JSON.stringify({ content }) }); await loadNotes(id); await reload(); toast('Note saved'); }
    catch (e) { toast(e instanceof Error ? e.message : 'Could not save note'); }
  }
  async function assign(id: string) {
    const current = cases.find((c) => c.id === id)?.assignedTo || '';
    const assignedTo = window.prompt('Assign to officer (leave blank to unassign)', current); if (assignedTo === null) return;
    await patchCase(id, 'assignment', { assignedTo }, assignedTo.trim() ? `Assigned to ${assignedTo}` : 'Case unassigned');
  }
  async function loadNotes(id: string) { try { setCaseNotes(await jsonApi<Array<{id:string;actor:string;content:string;createdAt:string}>>('/cases/' + id + '/notes')); } catch { setCaseNotes([]); } }
  async function loadCaseMessages(id: string) { try { setCaseMessages(await jsonApi<Array<{id:string;senderRole:string;content:string;createdAt:string}>>(`/cases/${id}/messages`)); } catch { setCaseMessages([]); } }
  async function replyToCitizen(id: string) { const content=window.prompt('Reply to the citizen'); if(content===null||!content.trim())return; try{await jsonApi(`/cases/${id}/messages`,{method:'POST',body:JSON.stringify({content})});await loadCaseMessages(id);toast('Reply sent to the citizen');}catch(e){toast(e instanceof Error?e.message:'Could not send reply');} }
  async function uploadFile(caseId: string, file: File) {
    const body = new FormData(); body.append('file', file);
    try { await jsonApi(`/cases/${caseId}/documents`, { method: 'POST', body }); await reload(); toast('Document uploaded and extracted'); }
    catch (e) { toast(e instanceof Error ? e.message : 'Upload failed'); }
  }
  async function reviewDocument(doc: Doc, status: 'Verified' | 'Flagged') {
    const note = window.prompt(status === 'Verified' ? 'Review note (optional)' : 'Describe the issue to flag'); if (note === null) return;
    if (status === 'Flagged' && !note.trim()) { toast('Add a note describing the issue.'); return; }
    try { await jsonApi(`/documents/${doc.id}/review`, { method: 'PATCH', body: JSON.stringify({ status, note }) }); await reload(); toast(`Document marked ${status.toLowerCase()}`); }
    catch (e) { toast(e instanceof Error ? e.message : 'Review could not be saved'); }
  }
  async function deleteDocument(doc: Doc) {
    if (!window.confirm(`Delete ${doc.name}? This also removes its indexed text.`)) return;
    try { await jsonApi(`/documents/${doc.id}`, { method: 'DELETE' }); setOpenDocument(null); await reload(); toast('Document deleted'); }
    catch (e) { toast(e instanceof Error ? e.message : 'Delete failed'); }
  }
  async function addKnowledge(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); const form = new FormData(e.currentTarget);
    try { await jsonApi('/knowledge', { method: 'POST', body: JSON.stringify(Object.fromEntries(form.entries())) }); e.currentTarget.reset(); await reload(); toast('Knowledge source added for review'); }
    catch (e) { toast(e instanceof Error ? e.message : 'Could not add source'); }
  }
  async function reviewKnowledge(item: Knowledge, status: 'Verified' | 'Flagged') {
    try { await jsonApi(`/knowledge/${item.id}/review`, { method: 'PATCH', body: JSON.stringify({ status }) }); await reload(); toast(`Source ${status.toLowerCase()}`); }
    catch (e) { toast(e instanceof Error ? e.message : 'Could not update source'); }
  }
  async function deleteKnowledge(item: Knowledge) {
    if (!window.confirm(`Delete ${item.title}?`)) return;
    try { await jsonApi(`/knowledge/${item.id}`, { method: 'DELETE' }); await reload(); toast('Source deleted'); }
    catch (e) { toast(e instanceof Error ? e.message : 'Delete failed'); }
  }

  const filteredCases = useMemo(() => {
    let result = cases.filter((c) => (statusFilter === 'All cases' || c.status === statusFilter) && `${c.id} ${c.citizen} ${c.service} ${c.district} ${c.assignedTo}`.toLowerCase().includes(query.toLowerCase()));
    result = [...result].sort((a, b) => sortBy === 'applicant' ? a.citizen.localeCompare(b.citizen) : sortBy === 'status' ? a.status.localeCompare(b.status) : new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
    return result;
  }, [cases, statusFilter, query, sortBy]);
  const shownCases = filteredCases.slice((pageNum - 1) * rowsPerPage, pageNum * rowsPerPage);
  const pages = Math.max(1, Math.ceil(filteredCases.length / rowsPerPage));
  useEffect(() => { setPageNum(1); }, [query, statusFilter, sortBy]);

  if (booting) return <div className="boot-screen"><div className="brand-mark"><i/><i/><i/><i/></div><p>{pageText('Connecting…')}</p></div>;
  if (!user) return <LoginScreen t={pageText} language={language} setLanguage={setLanguage} busy={loginBusy} error={loginError} onSignIn={signIn} onGuest={exploreGuest} onAccessGranted={(account)=>{setUser(account);setPage('dashboard');}} />;

  const nav: Array<{ id: Page; label: string; icon: typeof LayoutDashboard }> = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard }, { id: 'queue', label: 'Case queue', icon: FolderOpen }, { id: 'documents', label: 'Document review', icon: FileCheck2 }, { id: 'citizens', label: 'Citizens', icon: UsersRound }, { id: 'knowledge', label: 'Knowledge library', icon: BookOpen }, { id: 'assistant', label: 'Knowledge assistant', icon: BookOpen }, { id: 'activity', label: 'Activity log', icon: Activity }, { id: 'guide', label: 'Officer guide', icon: CircleHelp }, ...(user.role === 'admin' ? [{ id: 'access' as Page, label: 'Staff access requests', icon: ShieldCheck }] : []),
  ];
  const navigate = (p: Page) => { setPage(p); setMobileNav(false); setRowMenu(''); };
  const openCase = (id: string, tab: Tab = 'overview') => { setSelectedId(id); setCaseTab(tab); navigate('case'); void loadNotes(id); void loadCaseMessages(id); };

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'open' : ''}`}>
      <div className="brand"><div className="brand-mark"><i/><i/><i/><i/></div><div><b>sama</b><small>{pageText('Officer workspace').toUpperCase()}</small></div><button className="icon-btn mobile-only" onClick={()=>setMobileNav(false)} aria-label="Close navigation"><X size={18}/></button></div>
      <div className="office-switch"><div className="office-emblem">{user.role === 'guest' ? 'G' : user.role.slice(0,2).toUpperCase()}</div><div><b>{user.role === 'guest' ? 'Guest sandbox' : user.role === 'admin' ? 'Administrator' : 'Officer workspace'}</b><small>{user.email}</small></div><ChevronDown size={15}/></div>
      <div className="nav-label">{pageText('Workspace')}</div><nav className="nav">{nav.map((item) => <button key={item.id} className={`nav-item ${page===item.id?'active':''}`} onClick={()=>navigate(item.id)}><item.icon size={17}/>{pageText(item.label)}{item.id==='queue'&&<span className="nav-count">{cases.length}</span>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="sandbox-badge"><ShieldCheck size={15}/><span>{user.role==='guest'?'Private guest data sandbox':'Authenticated session'}</span></div><button className="nav-item logout-link" onClick={()=>void logout()}><LogOut size={16}/>{pageText('Logout')}</button><div className="profile"><div className="avatar user-avatar">{initials(user.email.split('@')[0])}</div><div className="profile-text"><b>{user.email}</b><small>{user.role}</small></div><button className="quiet-btn" aria-label={pageText('Logout')} onClick={()=>void logout()}><LogOut size={15}/></button></div></div>
    </aside>
    {mobileNav&&<button className="scrim" onClick={()=>setMobileNav(false)} aria-label="Close navigation"/>}
    <main className="main-area">
      <header className="topbar"><div className="crumb"><button className="icon-btn menu-toggle" onClick={()=>setMobileNav(true)} aria-label="Open navigation"><Menu size={19}/></button><span>{pageText('Officer workspace')}</span><ChevronRight size={14}/><b>{pageText(page==='case'?'Case queue':nav.find((n)=>n.id===page)?.label||'Dashboard')}</b></div><div className="top-actions"><div className={`system-status ${apiOnline===false?'offline':''}`}><i/>{apiOnline===null?pageText('Connecting…'):apiOnline?pageText('API connected'):pageText('API unavailable')}</div><span className="top-divider"/><label className="language-picker" aria-label={pageText('Language')}><Globe2 size={15}/><select value={language} onChange={(e)=>setLanguage(e.target.value as Language)}><option value="en">EN</option><option value="kn">ಕನ್ನಡ</option><option value="hi">हिन्दी</option></select></label><button className="icon-btn theme-toggle" title={pageText('Theme')} aria-label={pageText('Theme')} onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={17}/>:<Moon size={17}/>}</button><div className="notification-wrap"><button className="icon-btn notification" aria-label="Notifications" onClick={()=>setNotificationOpen(!notificationOpen)}><Activity size={17}/>{activity.length>0&&<i/>}</button>{notificationOpen&&<div className="notification-pop"><b>{pageText('Activity log')}</b>{activity.slice(0,5).map((a)=><button key={a.id} onClick={()=>{navigate('activity');setNotificationOpen(false);}}><span>{a.action}</span><small>{fmtDate(a.createdAt)}</small></button>)}{activity.length===0&&<p className="muted">{pageText('No activity yet')}</p>}<button className="text-link" onClick={()=>{navigate('activity');setNotificationOpen(false);}}>View all activity</button></div>}</div><button className="avatar top-avatar" aria-label={pageText('Logout')} onClick={()=>void logout()}>{initials(user.email.split('@')[0])}</button></div></header>
      <div className="page-content">
        {loadError&&<div className="error-banner"><span>{loadError}</span><button onClick={()=>void reload()}>{pageText('Try again')}</button></div>}
        {loading&&cases.length===0&&documents.length===0&&page!=='dashboard'&&<PageSkeleton/>}
        {page==='dashboard'&&<Dashboard t={pageText} cases={cases} loading={loading} onNew={()=>setShowCreate(true)} onOpen={(id)=>openCase(id)} onNavigate={navigate} />}
        {page==='queue'&&<QueuePage t={pageText} cases={shownCases} total={filteredCases.length} pageNum={pageNum} pages={pages} query={query} setQuery={setQuery} filter={statusFilter} setFilter={setStatusFilter} sortBy={sortBy} setSortBy={setSortBy} onNew={()=>setShowCreate(true)} onOpen={openCase} rowMenu={rowMenu} setRowMenu={setRowMenu} onAssign={assign} onStatus={changeStatus} onNote={addNote} onPage={setPageNum} />}
        {page==='case'&&selected&&<CaseWorkspace t={pageText} language={language} item={selected} tab={caseTab} setTab={setCaseTab} notes={caseNotes} messages={caseMessages} onReply={()=>void replyToCitizen(selected.id)} onBack={()=>navigate('queue')} onStatus={(s)=>void changeStatus(selected.id,s)} onAssign={()=>void assign(selected.id)} onNote={()=>void addNote(selected.id)} onUpload={(f)=>void uploadFile(selected.id,f)} onOpenDoc={setOpenDocument} onReview={reviewDocument} onDeleteDoc={deleteDocument} activity={activity.filter((a)=>a.resourceId===selected.id)} />}
        {page==='case'&&!selected&&<EmptyState title={pageText('No cases yet')} description="Create or select a case to open its workspace." action={pageText('Create case')} onAction={()=>setShowCreate(true)} />}
        {page==='documents'&&<DocumentsPage t={pageText} docs={documents} loading={loading} onOpen={setOpenDocument} onReview={reviewDocument} onDelete={deleteDocument} onCase={(id)=>openCase(id,'documents')} />}
        {page==='citizens'&&<CitizensPage t={pageText} citizens={citizens} loading={loading} onOpen={(name)=>{const c=cases.find((x)=>x.citizen===name);if(c)openCase(c.id);}} />}
        {page==='knowledge'&&<KnowledgePage t={pageText} items={knowledge} onAdd={addKnowledge} onReview={reviewKnowledge} onDelete={deleteKnowledge} />}
        {page==='activity'&&<ActivityPage t={pageText} events={activity} loading={loading} onOpen={(id)=>openCase(id)} />}
        {page==='guide'&&<GuidePage t={pageText} />}
        {page==='access'&&user.role==='admin'&&<StaffAccessPage requests={staffRequests} error={staffRequestsError} loading={staffRequestsLoading} onReview={reviewStaffRequest} />}
        {page==='assistant'&&<div className="assistant-page"><div className="page-title"><div><span className="eyebrow">SAMA AI</span><h1>{pageText('General assistant')}</h1><p>Ask general questions using reviewed sources from your knowledge library.</p></div></div><ChatPanel t={pageText} caseId={null} language={language} onOpenSource={(s)=>openCitation(s,setOpenDocument,documents)} /></div>}
        <footer className="page-footer"><span><ShieldCheck size={13}/>{user.role==='guest'?'Guest sandbox · changes are private to this session':'Authenticated officer workspace'}</span><span>Sama AI · v0.2</span></footer>
      </div>
    </main>
    {showCreate&&<CreateCaseModal t={pageText} onClose={()=>setShowCreate(false)} onSubmit={createCase} />}
    {openDocument&&<DocumentModal t={pageText} doc={openDocument} onClose={()=>setOpenDocument(null)} onVerify={()=>void reviewDocument(openDocument,'Verified')} onFlag={()=>void reviewDocument(openDocument,'Flagged')} onDelete={()=>void deleteDocument(openDocument)} />}
    {notice&&<div className="toast" role="status"><span>{notice}</span><button onClick={()=>setNotice('')} aria-label="Dismiss notification"><X size={15}/></button></div>}
  </div>;
}

function openCitation(source: Source, setDoc: (d: Doc | null)=>void, docs: Doc[]) {
  if(source.type==='document'){ const doc=docs.find((d)=>d.id===source.id); if(doc)setDoc(doc); }
  else window.open(source.url||`${API}/knowledge/${source.id}`,'_blank','noopener,noreferrer');
}

function LoginScreen({t,language,setLanguage,busy,error,onSignIn,onGuest,onAccessGranted}:{t:(s:string)=>string;language:Language;setLanguage:(l:Language)=>void;busy:boolean;error:string;onSignIn:(e:FormEvent<HTMLFormElement>)=>void;onGuest:()=>void;onAccessGranted:(user:User)=>void}) {
  const [show,setShow]=useState(false); const [api,setApi]=useState<boolean|null>(null); const [mode,setMode]=useState<'login'|'request'|'accept'>(()=>new URLSearchParams(window.location.search).has('invite')?'accept':'login'); const [formError,setFormError]=useState(''); const [success,setSuccess]=useState(''); const [requestBusy,setRequestBusy]=useState(false);
  useEffect(()=>{fetch(`${API.replace(/\/api$/,'')}/health`).then((r)=>setApi(r.ok)).catch(()=>setApi(false));},[]);
  async function submitStaffRequest(e:FormEvent<HTMLFormElement>){e.preventDefault();const formElement=e.currentTarget;setRequestBusy(true);setFormError('');setSuccess('');const form=new FormData(formElement);try{const res=await fetch(`${API}/auth/staff-access-requests`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(form.entries()))});const body=await res.json();if(!res.ok)throw new Error(body.detail||'Could not submit access request.');setSuccess('Request submitted. An administrator will review it. No account is active until you receive and accept an invitation.');formElement.reset();}catch(e){setFormError(e instanceof Error?e.message:'Could not submit access request.');}finally{setRequestBusy(false);}}
  async function acceptInvitation(e:FormEvent<HTMLFormElement>){e.preventDefault();setRequestBusy(true);setFormError('');const form=new FormData(e.currentTarget);const token=new URLSearchParams(window.location.search).get('invite')||String(form.get('token')||'');try{const res=await fetch(`${API}/auth/staff-invitations/accept`,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({email:form.get('email'),token,password:form.get('password')})});const body=await res.json();if(!res.ok)throw new Error(body.detail||'Could not accept invitation.');window.history.replaceState({},'',window.location.pathname);onAccessGranted(body);}catch(e){setFormError(e instanceof Error?e.message:'Could not accept invitation.');}finally{setRequestBusy(false);}}
  return <div className="login-shell"><div className="login-art"><div className="brand"><div className="brand-mark"><i/><i/><i/><i/></div><div><b>sama</b><small>{t('Officer workspace').toUpperCase()}</small></div></div><div className="login-art-copy"><span className="eyebrow">SECURE CASE OPERATIONS</span><h1>Public service,<br/><em>made clearer.</em></h1><p>A calm workspace for reviewing applications, documents and verified guidance.</p><div className="art-orbit"><div className="orbit-center"><ShieldCheck size={33}/></div><span className="orbit-node n1"><FileText size={17}/></span><span className="orbit-node n2"><UsersRound size={17}/></span><span className="orbit-node n3"><BookOpen size={17}/></span></div></div><div className="login-legal">Sama AI · Officer workspace</div></div><div className="login-side"><div className="login-lang"><Globe2 size={15}/><select value={language} onChange={(e)=>setLanguage(e.target.value as Language)} aria-label={t('Language')}><option value="en">English</option><option value="kn">ಕನ್ನಡ</option><option value="hi">हिन्दी</option></select></div><div className="login-card"><div className="login-mobile-brand"><div className="brand-mark"><i/><i/><i/><i/></div><b>sama</b></div>{mode==='login'?<form onSubmit={onSignIn}><span className="eyebrow">WELCOME BACK</span><h2>{t('Sign in to Sama')}</h2><p>Use your department account to continue.</p><label>{t('Email address')}<input name="email" type="email" autoComplete="username" required maxLength={254} placeholder="name@department.gov.in"/></label><label>{t('Password')}<span className="password-field"><input name="password" type={show?'text':'password'} autoComplete="current-password" required maxLength={256}/><button type="button" aria-label={t('Show password')} onClick={()=>setShow(!show)}>{show?'Hide':'Show'}</button></span></label><label className="remember-row"><input type="checkbox" name="remember" defaultChecked/><span>{t('Remember me')}</span></label>{error&&<div className="form-error" role="alert">{error}</div>}<button className="primary-btn login-submit" disabled={busy}>{busy?'Signing in…':t('Sign in')}</button><div className="login-separator"><span>or</span></div><button type="button" className="outline-btn guest-btn" onClick={onGuest} disabled={busy}>{t('Explore as guest')}<ArrowUpRight size={15}/></button><button type="button" className="text-link access-request-link" onClick={()=>{setMode('request');setFormError('');setSuccess('');}}>Request government staff access</button><small className={`login-api ${api===false?'offline':''}`}><i/>{api===null?'Checking service…':api?'Service is available':'API unavailable — start the local services'}</small></form>:mode==='request'?<form onSubmit={submitStaffRequest}><span className="eyebrow">STAFF ONBOARDING</span><h2>Request government staff access</h2><p>Submit your official department details for administrator review.</p><label>Full name<input name="fullName" required minLength={2} maxLength={160} autoComplete="name"/></label><label>Government email<input name="email" type="email" required maxLength={254} placeholder="name@department.gov.in"/></label><label>Department<input name="department" required minLength={2} maxLength={160}/></label><label>Position or title<input name="position" maxLength={120}/></label><label>Reason for access<textarea name="reason" required minLength={10} maxLength={2000} rows={3}/></label>{formError&&<div className="form-error" role="alert">{formError}</div>}{success&&<div className="success-message" role="status">{success}</div>}<button className="primary-btn login-submit" disabled={requestBusy}>{requestBusy?'Submitting…':'Submit access request'}</button><button type="button" className="text-link" onClick={()=>setMode('login')}>Back to sign in</button></form>:<form onSubmit={acceptInvitation}><span className="eyebrow">INVITATION</span><h2>Activate staff account</h2><p>Use the official email that received the invitation. Invitations expire after 24 hours.</p><label>Government email<input name="email" type="email" required defaultValue={new URLSearchParams(window.location.search).get('email')||''} autoComplete="email"/></label>{!new URLSearchParams(window.location.search).get('invite')&&<label>Invitation token<input name="token" required minLength={32} maxLength={200}/></label>}<label>Create password<span className="password-field"><input name="password" type={show?'text':'password'} required minLength={12} maxLength={256} autoComplete="new-password"/><button type="button" onClick={()=>setShow(!show)}>{show?'Hide':'Show'}</button></span></label><small>Use at least 12 characters.</small>{formError&&<div className="form-error" role="alert">{formError}</div>}<button className="primary-btn login-submit" disabled={requestBusy}>{requestBusy?'Activating…':'Accept invitation'}</button><button type="button" className="text-link" onClick={()=>setMode('login')}>Back to sign in</button></form>}</div></div></div>;
}

function StaffAccessPage({requests,error,loading,onReview}:{requests:StaffRequest[];error:string;loading:boolean;onReview:(id:string,status:'Approved'|'Rejected')=>void}) { return <><section className="page-title"><div><span className="eyebrow">ADMINISTRATION</span><h1>Staff access requests</h1><p>Review official email requests and issue one-time invitations.</p></div></section>{loading?<SkeletonRows/>:error?<div className="form-error" role="alert">{error}</div>:requests.length===0?<EmptyState title="No pending requests" description="New government staff requests will appear here for review."/>:<div className="access-request-list">{requests.map((request)=><article className="panel access-request-card" key={request.id}><div className="access-request-heading"><div><h2>{request.fullName}</h2><a href={`mailto:${request.email}`}>{request.email}</a></div><span className="status-pill review"><i/>{request.status}</span></div><dl><div><dt>Department</dt><dd>{request.department}</dd></div><div><dt>Position</dt><dd>{request.position||'Not provided'}</dd></div><div><dt>Submitted</dt><dd>{fmtDate(request.createdAt)}</dd></div></dl><div className="access-request-reason"><b>Reason for access</b><p>{request.reason}</p></div>{request.reviewNote&&<p className="muted">Previous review note: {request.reviewNote}</p>}<div className="access-request-actions"><button className="primary-btn" onClick={()=>onReview(request.id,'Approved')}>Approve and create invitation</button><button className="outline-btn" onClick={()=>onReview(request.id,'Rejected')}>Decline request</button></div></article>)}</div>}</>; }

function Dashboard({t,cases,loading,onNew,onOpen,onNavigate}:{t:(s:string)=>string;cases:CaseItem[];loading:boolean;onNew:()=>void;onOpen:(id:string)=>void;onNavigate:(p:Page)=>void}) {
  const review=cases.filter((c)=>c.status==='Needs review').length, progress=cases.filter((c)=>c.status==='In progress').length, waiting=cases.filter((c)=>c.status==='Needs documents').length;
 return <><section className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line"/>{new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date()).toUpperCase()}</div><h1>{t('Dashboard')}</h1><p>Live cases and document reviews in your workspace.</p></div><button className="primary-btn" onClick={onNew}><Plus size={15}/>{t('Create case')}</button></section><section className="stats-grid"><Stat label={t('Total cases')} value={cases.length} tone="blue" icon={<FolderOpen size={17}/>} /><Stat label={t('Needs review')} value={review} tone="amber" icon={<FileCheck2 size={17}/>} /><Stat label={t('In progress')} value={progress} tone="green" icon={<Activity size={17}/>} /><Stat label={t('Awaiting documents')} value={waiting} tone="violet" icon={<FileText size={17}/>} /></section><section className="panel dashboard-queue"><div className="panel-heading"><div><div className="section-kicker">CASE MANAGEMENT</div><h2>{t('Case queue')}</h2><p>Recently updated cases from your workspace.</p></div><button className="text-link" onClick={()=>onNavigate('queue')}>View queue <ArrowUpRight size={14}/></button></div>{loading?<SkeletonRows/>:cases.length?<div className="recent-grid">{cases.slice(0,5).map((c)=><button className="recent-case" key={c.id} onClick={()=>onOpen(c.id)}><span className="avatar case-avatar">{initials(c.citizen)}</span><span className="recent-main"><b>{c.citizen}</b><small>{c.service} · {c.district}</small></span><Status value={c.status} t={t}/><ArrowUpRight size={15}/></button>)}</div>:<EmptyState title={t('No cases yet')} description="Create a case to begin reviewing applications. Your queue will update from saved records." action={t('Create case')} onAction={onNew}/>}</section><div className="dashboard-shortcuts"><button className="shortcut-card" onClick={()=>onNavigate('documents')}><FileCheck2/><span><b>{t('Document review')}</b><small>{'Review uploaded files and OCR text.'}</small></span><ArrowUpRight/></button><button className="shortcut-card" onClick={()=>onNavigate('assistant')}><BookOpen/><span><b>{t('Knowledge assistant')}</b><small>Ask questions with reviewed source citations.</small></span><ArrowUpRight/></button></div></>;
}
function Stat({label,value,tone,icon}:{label:string;value:number;tone:string;icon:ReactNode}){return <div className="stat-card"><div className="stat-top"><span>{label}</span><i className={`stat-icon ${tone}`}>{icon}</i></div><div className="stat-value">{String(value).padStart(2,'0')}</div><div className="stat-delta">Saved records</div></div>;}
function Status({value,t}:{value:string;t?:(s:string)=>string}){const cls=value==='Needs review'?'review':value==='In progress'?'progress':value==='Needs documents'?'docs':value==='Received'?'received':value==='Rejected'?'rejected':'complete';return <span className={`status-pill ${cls}`}><i/>{t?t(value):value}</span>;}
function EmptyState({title,description,action,onAction}:{title:string;description:string;action?:string;onAction?:()=>void}){return <div className="empty-state"><div className="empty-mark"><FolderOpen size={23}/></div><h3>{title}</h3><p>{description}</p>{action&&onAction&&<button className="primary-btn" onClick={onAction}><Plus size={14}/>{action}</button>}</div>;}
function SkeletonRows(){return <div className="skeleton-list">{Array.from({length:4},(_,i)=><div className="skeleton-row" key={i}><i/><span/><span/><span/></div>)}</div>;}
function PageSkeleton(){return <div className="page-skeleton"><i/><i/><i/><i/></div>;}

function QueuePage(props:{t:(s:string)=>string;cases:CaseItem[];total:number;pageNum:number;pages:number;query:string;setQuery:(s:string)=>void;filter:string;setFilter:(s:string)=>void;sortBy:string;setSortBy:(s:string)=>void;onNew:()=>void;onOpen:(id:string,tab?:Tab)=>void;rowMenu:string;setRowMenu:(s:string)=>void;onAssign:(id:string)=>void;onStatus:(id:string,s:string)=>void;onNote:(id:string)=>void;onPage:(n:number)=>void}){
 const {t,cases,total,pageNum,pages,query,setQuery,filter,setFilter,sortBy,setSortBy,onNew,onOpen,rowMenu,setRowMenu,onAssign,onStatus,onNote,onPage}=props;
 return <><section className="page-title"><div><span className="eyebrow">WORKSPACE</span><h1>{t('Case queue')}</h1><p>Search, filter, sort and update case records.</p></div><button className="primary-btn" onClick={onNew}><Plus size={15}/>{t('New case')}</button></section><section className="panel queue-panel"><div className="queue-toolbar"><div className="tabs"><button className={filter==='All cases'?'selected':''} onClick={()=>setFilter('All cases')}>{t('All cases')} <span>{total}</span></button>{['Received','Needs review','In progress','Needs documents','Completed','Rejected'].map((s)=><button className={filter===s?'selected':''} key={s} onClick={()=>setFilter(s)}>{t(s)}</button>)}</div><div className="queue-actions"><label className="search-box"><Search size={15}/><input id="case-search" placeholder={`${t('Search cases')}…`} value={query} onChange={(e)=>setQuery(e.target.value)}/><kbd>Ctrl K</kbd></label><select className="sort-select" aria-label="Sort cases" value={sortBy} onChange={(e)=>setSortBy(e.target.value)}><option value="updated">Recently updated</option><option value="applicant">Applicant</option><option value="status">Status</option></select></div></div><div className="case-table-wrap"><table className="case-table"><thead><tr><th>{t('Applicant name')}</th><th>{t('Service requested')}</th><th>{t('Case status')}</th><th>{t('Assign to')}</th><th>UPDATED</th><th/></tr></thead><tbody>{cases.length?cases.map((c)=><tr key={c.id} onClick={()=>onOpen(c.id)}><td><div className="applicant-cell"><div className="avatar case-avatar">{initials(c.citizen)}</div><div><b>{c.citizen}</b><small>{c.id} · {c.district}</small></div></div></td><td><div className="service-cell">{c.service}<small>{c.priority} priority</small></div></td><td><Status value={c.status} t={t}/></td><td>{c.assignedTo||<span className="muted">Unassigned</span>}</td><td className="updated-cell">{fmtDate(c.updatedAt)}</td><td className="menu-cell"><button className="row-more" aria-label="Case actions" onClick={(e)=>{e.stopPropagation();setRowMenu(rowMenu===c.id?'':c.id);}}><MoreHorizontal size={17}/></button>{rowMenu===c.id&&<div className="row-menu" onClick={(e)=>e.stopPropagation()}><button onClick={()=>onOpen(c.id)}>{t('View')}</button><button onClick={()=>onAssign(c.id)}>{t('Assign to')}</button><select aria-label="Change case status" value={c.status} onChange={(e)=>onStatus(c.id,e.target.value)}>{['Received','Needs review','In progress','Needs documents','Completed','Rejected'].map((s)=><option key={s} value={s}>{t(s)}</option>)}</select><button onClick={()=>onNote(c.id)}>{t('Add note')}</button></div>}</td></tr>):<tr><td colSpan={6}><EmptyState title={t('No cases yet')} description={total===0?'Create a case to begin.':'No cases match the selected filter.'} action={t('Create case')} onAction={onNew}/></td></tr>}</tbody></table></div><div className="table-footer"><span>Showing {total?((pageNum-1)*8+1):0}–{Math.min(total,pageNum*8)} of {total} cases</span><div><button disabled={pageNum===1} onClick={()=>onPage(pageNum-1)} aria-label="Previous page"><ChevronLeft size={15}/></button><span className="page-indicator">{pageNum} / {pages}</span><button disabled={pageNum===pages} onClick={()=>onPage(pageNum+1)} aria-label="Next page"><ChevronRight size={15}/></button></div></div></section></>;
}

function CreateCaseModal({t,onClose,onSubmit}:{t:(s:string)=>string;onClose:()=>void;onSubmit:(e:FormEvent<HTMLFormElement>)=>void}){return <div className="modal-backdrop" onMouseDown={(e)=>{if(e.target===e.currentTarget)onClose();}}><form className="modal-card" onSubmit={onSubmit}><div className="modal-heading"><div><span className="section-kicker">CASE MANAGEMENT</span><h2>{t('Create case')}</h2></div><button type="button" className="quiet-btn" aria-label="Close" onClick={onClose}><X size={18}/></button></div><label>{t('Applicant name')}<input name="citizen" required maxLength={160}/></label><label>{t('Service requested')}<input name="service" required maxLength={160}/></label><label>{t('District')}<input name="district" required maxLength={120}/></label><label>{t('Priority')}<select name="priority"><option>Normal</option><option>High</option><option>Low</option></select></label><label>{t('Case notes')}<textarea name="summary" rows={3} maxLength={4000}/></label><div className="modal-actions"><button type="button" className="outline-btn" onClick={onClose}>{t('Cancel')}</button><button className="primary-btn"><Plus size={14}/>{t('Create')}</button></div></form></div>;}

function CaseWorkspace(props:{t:(s:string)=>string;language:Language;item:CaseItem;tab:Tab;setTab:(t:Tab)=>void;notes:Array<{id:string;actor:string;content:string;createdAt:string}>;messages:Array<{id:string;senderRole:string;content:string;createdAt:string}>;onReply:()=>void;onBack:()=>void;onStatus:(s:string)=>void;onAssign:()=>void;onNote:()=>void;onUpload:(f:File)=>void;onOpenDoc:(d:Doc)=>void;onReview:(d:Doc,s:'Verified'|'Flagged')=>void;onDeleteDoc:(d:Doc)=>void;activity:ActivityEvent[]}){
 const {t,language,item,tab,setTab,notes,messages,onReply,onBack,onStatus,onAssign,onNote,onUpload,onOpenDoc,onReview,onDeleteDoc,activity}=props; const [drag,setDrag]=useState(false); const input=useRef<HTMLInputElement>(null);
 return <><div className="case-breadcrumb"><button className="text-link" onClick={onBack}><ArrowLeft size={14}/>{t('Case queue')}</button><ChevronRight size={13}/><span>{item.id}</span></div><section className="case-page-header"><div className="detail-person"><div className="avatar detail-avatar">{initials(item.citizen)}</div><div><span className="eyebrow">{item.id} · {item.district}</span><h1>{item.citizen}</h1><p>{item.service}</p></div></div><div className="case-page-actions"><Status value={item.status} t={t}/><button className="outline-btn" onClick={onAssign}>{item.assignedTo||t('Assign to')}</button><button className="outline-btn" onClick={onNote}>{t('Add note')}</button></div></section><section className="panel case-workspace"><div className="detail-tabs"><button className={tab==='overview'?'active':''} onClick={()=>setTab('overview')}>{t('Overview')}</button><button className={tab==='documents'?'active':''} onClick={()=>setTab('documents')}>{t('Documents')} <span>{item.documents.length}</span></button><button className={tab==='activity'?'active':''} onClick={()=>setTab('activity')}>{t('Activity')}</button></div>
 {tab==='overview'&&<div className="case-overview-grid"><div className="panel-lite"><h3>{t('Case overview')}</h3><div className="info-row"><span>{t('Service requested')}</span><b>{item.service}</b></div><div className="info-row"><span>{t('District')}</span><b>{item.district}</b></div><div className="info-row"><span>{t('Priority')}</span><b>{item.priority}</b></div><div className="info-row"><span>{t('Assign to')}</span><b>{item.assignedTo||'Unassigned'}</b></div><div className="info-row"><span>{t('Case status')}</span><select value={item.status} onChange={(e)=>onStatus(e.target.value)}>{['Received','Needs review','In progress','Needs documents','Completed','Rejected'].map((s)=><option key={s} value={s}>{t(s)}</option>)}</select></div><div className="note-block"><b>{t('Case notes')}</b><p>{item.summary||'No initial notes.'}</p>{notes.map((n)=><blockquote key={n.id}>{n.content}<small>{n.actor} · {fmtDate(n.createdAt)}</small></blockquote>)}{item.source==="Citizen portal"&&<div className="citizen-thread"><b>Citizen conversation</b>{messages.map(m=><blockquote key={m.id}>{m.content}<small>{m.senderRole} · {fmtDate(m.createdAt)}</small></blockquote>)}<button className="outline-btn" onClick={onReply}>Reply to citizen</button></div>}<button className="outline-btn" onClick={onNote}>+ {t('Add note')}</button></div></div><ChatPanel t={t} caseId={item.id} language={language} onOpenSource={(s)=>{const d=item.documents.find((x)=>x.id===s.id);if(d)onOpenDoc(d);else window.open(s.url||`${API}/knowledge/${s.id}`,'_blank','noopener,noreferrer');}}/></div>}
 {tab==='documents'&&<div className="workspace-docs"><div className={`dropzone ${drag?'dragging':''}`} onDragOver={(e)=>{e.preventDefault();setDrag(true);}} onDragLeave={()=>setDrag(false)} onDrop={(e)=>{e.preventDefault();setDrag(false);const f=e.dataTransfer.files[0];if(f)onUpload(f);}} onClick={()=>input.current?.click()} role="button" tabIndex={0} onKeyDown={(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();input.current?.click();}}}><input ref={input} hidden type="file" accept=".pdf,.png,.jpg,.jpeg,.tiff" onChange={(e)=>{const f=e.target.files?.[0];if(f)onUpload(f);e.currentTarget.value='';}}/><FileText size={21}/><b>Drop PDF or image here, or browse</b><small>Maximum 20 MB · OCR text is extracted on upload</small></div>{item.documents.length?<div className="document-grid">{item.documents.map((d)=><DocumentCard key={d.id} t={t} doc={d} onOpen={()=>onOpenDoc(d)} onVerify={()=>onReview(d,'Verified')} onFlag={()=>onReview(d,'Flagged')} onDelete={()=>onDeleteDoc(d)}/>)}</div>:<EmptyState title={t('No documents yet')} description="Upload a PDF or image to begin document review." />}</div>}
 {tab==='activity'&&<ActivityTimeline events={activity} empty={t('No activity yet')} />}</section></>;
}

function DocumentCard({t,doc,onOpen,onVerify,onFlag,onDelete}:{t:(s:string)=>string;doc:Doc;onOpen:()=>void;onVerify:()=>void;onFlag:()=>void;onDelete:()=>void}){return <article className="doc-card"><div className="doc-card-top"><span className="doc-icon"><FileText size={17}/></span><Status t={t} value={doc.reviewStatus==='Pending review'?'Needs review':doc.reviewStatus==='Flagged'?'Rejected':'Completed'}/></div><b>{doc.name}</b><small>{doc.extractedText?.length.toLocaleString()||0} extracted characters · {fmtDate(doc.createdAt)}</small>{doc.reviewNote&&<p className="review-note">{doc.reviewNote}</p>}<div className="doc-actions"><button onClick={onOpen}>{t('Open document')}</button>{doc.reviewStatus!=='Verified'&&<button onClick={onVerify}><Check size={13}/>{t('Verify')}</button>}{doc.reviewStatus!=='Flagged'&&<button onClick={onFlag}>⚑ {t('Flag issue')}</button>}<button className="danger-quiet" onClick={onDelete} aria-label={t('Delete')}><Trash2 size={14}/></button></div></article>;}

function DocumentsPage({t,docs,loading,onOpen,onReview,onDelete,onCase}:{t:(s:string)=>string;docs:Doc[];loading:boolean;onOpen:(d:Doc)=>void;onReview:(d:Doc,s:'Verified'|'Flagged')=>void;onDelete:(d:Doc)=>void;onCase:(id:string)=>void}){const pending=docs.filter((d)=>d.reviewStatus==='Pending review');return <><section className="page-title"><div><span className="eyebrow">WORKSPACE</span><h1>{t('Document review')}</h1><p>Uploaded files, extracted text and officer review decisions.</p></div><span className="count-pill">{pending.length} pending</span></section>{loading?<SkeletonRows/>:docs.length?<div className="document-grid">{docs.map((d)=><article className="doc-card" key={d.id}><div className="doc-card-top"><span className="doc-icon"><FileText size={17}/></span><Status value={d.reviewStatus==='Pending review'?'Needs review':d.reviewStatus==='Flagged'?'Rejected':'Completed'}/></div><b>{d.name}</b><small>{d.citizen} · {d.service} · {fmtDate(d.createdAt)}</small><small>{d.extractedText?.length.toLocaleString()||0} extracted characters</small><div className="doc-actions"><button onClick={()=>onOpen(d)}>{t('Open document')}</button><button onClick={()=>onCase(d.caseId)}>Open case</button>{d.reviewStatus!=='Verified'&&<button onClick={()=>onReview(d,'Verified')}>{t('Verify')}</button>}{d.reviewStatus!=='Flagged'&&<button onClick={()=>onReview(d,'Flagged')}>{t('Flag issue')}</button>}<button className="danger-quiet" onClick={()=>onDelete(d)}><Trash2 size={14}/></button></div></article>)}</div>:<EmptyState title={t('No documents yet')} description="Upload a document from a case workspace; reviewed files appear here."/>}</>;}

function DocumentFrame({doc}:{doc:Doc}){const [url,setUrl]=useState('');const [error,setError]=useState('');useEffect(()=>{let blobUrl='';void authFetch(`/documents/${doc.id}/file`).then(async r=>{if(!r.ok)throw new Error('Could not load this document preview.');blobUrl=URL.createObjectURL(await r.blob());setUrl(blobUrl);}).catch(e=>setError(e instanceof Error?e.message:'Preview unavailable'));return()=>{if(blobUrl)URL.revokeObjectURL(blobUrl);};},[doc.id]);return url?<iframe title={doc.name} src={url}/>:<div className="preview-loading">{error||'Loading preview…'}</div>;}
function DocumentModal({t,doc,onClose,onVerify,onFlag,onDelete}:{t:(s:string)=>string;doc:Doc;onClose:()=>void;onVerify:()=>void;onFlag:()=>void;onDelete:()=>void}){return <div className="modal-backdrop" onMouseDown={(e)=>{if(e.target===e.currentTarget)onClose();}}><section className="viewer-card"><div className="modal-heading"><div><span className="section-kicker">{t('Document review')} · {doc.reviewStatus}</span><h2>{doc.name}</h2></div><button className="quiet-btn" onClick={onClose} aria-label="Close"><X size={18}/></button></div><div className="viewer-content"><DocumentFrame doc={doc}/><div><h3>Extracted text</h3><pre>{doc.extractedText||'No text could be extracted. Check document quality or OCR support.'}</pre></div></div><div className="modal-actions"><button className="danger-quiet" onClick={onDelete}>{t('Delete')}</button>{doc.reviewStatus!=='Verified'&&<button className="primary-btn" onClick={onVerify}><Check size={14}/>{t('Verify')}</button>}{doc.reviewStatus!=='Flagged'&&<button className="outline-btn" onClick={onFlag}>{t('Flag issue')}</button>}</div></section></div>;}

function ActivityPage({t,events,loading,onOpen}:{t:(s:string)=>string;events:ActivityEvent[];loading:boolean;onOpen:(id:string)=>void}){return <><section className="page-title"><div><span className="eyebrow">AUDIT</span><h1>{t('Activity log')}</h1><p>Recorded logins and changes from your account.</p></div></section>{loading?<SkeletonRows/>:events.length?<ActivityTimeline events={events} empty={t('No activity yet')} onOpen={onOpen}/>:<EmptyState title={t('No activity yet')} description="Sign-ins, reviews, uploads and status updates will be recorded here."/>}</>;}
function ActivityTimeline({events,empty,onOpen}:{events:ActivityEvent[];empty:string;onOpen?:(id:string)=>void}){if(!events.length)return <div className="activity-timeline"><p className="muted">{empty}</p></div>;return <div className="activity-timeline">{events.map((e)=><div className="timeline-event" key={e.id}><i/><div><b>{e.action.replace(/[_:]/g,' ')}</b><small>{e.actor} · {fmtDate(e.createdAt)}</small></div>{e.resourceId&&onOpen&&<button className="text-link" onClick={()=>onOpen(e.resourceId!)}>Open record <ArrowUpRight size={13}/></button>}</div>)}</div>;}

function CitizensPage({t,citizens,loading,onOpen}:{t:(s:string)=>string;citizens:Array<{name:string;district:string;cases:number;services:string[];statuses:string[]}>;loading:boolean;onOpen:(name:string)=>void}){return <><section className="page-title"><div><span className="eyebrow">DIRECTORY</span><h1>{t('Citizens')}</h1><p>People represented by cases in your workspace.</p></div></section>{loading?<SkeletonRows/>:citizens.length?<div className="panel table-panel"><table className="case-table"><thead><tr><th>{t('Applicant name')}</th><th>{t('District')}</th><th>CASES</th><th>SERVICES</th><th/></tr></thead><tbody>{citizens.map((c)=><tr key={c.name} onClick={()=>onOpen(c.name)}><td><div className="applicant-cell"><div className="avatar case-avatar">{initials(c.name)}</div><b>{c.name}</b></div></td><td>{c.district}</td><td>{c.cases}</td><td>{c.services.join(', ')}</td><td><ArrowUpRight size={15}/></td></tr>)}</tbody></table></div>:<EmptyState title="No citizens yet" description="Citizen entries are created from cases you add."/>}</>;}

function KnowledgePage({t,items,onAdd,onReview,onDelete}:{t:(s:string)=>string;items:Knowledge[];onAdd:(e:FormEvent<HTMLFormElement>)=>void;onReview:(k:Knowledge,s:'Verified'|'Flagged')=>void;onDelete:(k:Knowledge)=>void}){return <><section className="page-title"><div><span className="eyebrow">VERIFIED SOURCES</span><h1>{t('Knowledge library')}</h1><p>Add, review and maintain the source material used by the assistant.</p></div></section><section className="panel knowledge-form-panel"><form className="knowledge-form" onSubmit={onAdd}><label>{t('Source title')}<input name="title" required maxLength={180}/></label><label>{t('Department')}<input name="department" maxLength={180}/></label><label>{t('Source URL')}<input name="sourceUrl" type="url" placeholder="https://…" maxLength={2000}/></label><label className="wide-label">{t('Content')}<textarea name="content" rows={5} required minLength={10} maxLength={100000} placeholder="Paste source text. Review it before marking verified."/></label><div className="form-end"><small>Sources start as pending review. Only verified sources are used by the assistant.</small><button className="primary-btn"><Plus size={14}/>{t('Add source')}</button></div></form></section>{items.length?<div className="knowledge-list">{items.map((k)=><article className="knowledge-card" key={k.id}><div className="knowledge-card-top"><div><span className="eyebrow">{k.department||'SOURCE'}</span><h3>{k.title}</h3><small>{k.sourceUrl||'No external URL'} · {fmtDate(k.createdAt)}</small></div><Status value={k.reviewStatus==='Pending review'?'Needs review':k.reviewStatus==='Flagged'?'Rejected':'Completed'}/></div><p>{k.content.slice(0,380)}{k.content.length>380?'…':''}</p><div className="doc-actions">{k.reviewStatus!=='Verified'&&<button onClick={()=>onReview(k,'Verified')}><Check size={13}/>{t('Verify')}</button>}{k.reviewStatus!=='Flagged'&&<button onClick={()=>onReview(k,'Flagged')}>{t('Flag issue')}</button>}<button className="danger-quiet" onClick={()=>onDelete(k)}><Trash2 size={14}/>{t('Delete')}</button></div></article>)}</div>:<EmptyState title="No knowledge sources" description="Add reviewed official material before asking the assistant for general guidance."/>}</>;}

function GuidePage({t}:{t:(s:string)=>string}){return <><section className="page-title"><div><span className="eyebrow">HELP CENTRE</span><h1>{t('Officer guide')}</h1><p>How to use the case and document workspace.</p></div></section><div className="guide-grid"><article className="guide-card"><span>01</span><h3>Create and manage cases</h3><p>Use Create case to record an applicant, requested service, district, priority and initial notes. Update case status and assignment from the case workspace. Every change is recorded in Activity.</p></article><article className="guide-card"><span>02</span><h3>Review documents</h3><p>Upload a PDF or image in the Documents tab. OCR text appears beside the file preview. Check both the source document and extracted text before marking a document verified or flagging an issue.</p></article><article className="guide-card"><span>03</span><h3>Use the knowledge assistant</h3><p>Only verified case documents and verified knowledge sources are included in retrieval. Answers include source citations. Verify the original source before acting on an answer.</p></article><article className="guide-card"><span>04</span><h3>Guest sandbox</h3><p>Guest changes are scoped to a private, temporary account. Guest sessions expire after one day; they cannot access another account’s records.</p></article><article className="guide-card"><span>05</span><h3>Privacy and security</h3><p>Use only records you are authorized to handle. Do not put passwords, secrets, or unrelated personal details in case notes or source text.</p></article></div></>;}

function ChatPanel({t,caseId,language,onOpenSource}:{t:(s:string)=>string;caseId:string|null;language:Language;onOpenSource:(s:Source)=>void}){
 const [messages,setMessages]=useState<Message[]>([]);const [question,setQuestion]=useState('');const [streaming,setStreaming]=useState(false);const [error,setError]=useState('');const [listening,setListening]=useState(false);const [voiceMessage,setVoiceMessage]=useState('');const [speaking,setSpeaking]=useState(false);const [copied,setCopied]=useState('');const bottom=useRef<HTMLDivElement>(null);const controller=useRef<AbortController|null>(null);const recognition=useRef<any>(null);
 const qs=caseId?`?caseId=${encodeURIComponent(caseId)}`:'';
 const loadHistory=useCallback(async()=>{try{setMessages(await jsonApi<Message[]>(`/assistant/history${qs}`));}catch(e){setError(e instanceof Error?e.message:'Could not load chat history');}},[qs]);
 useEffect(()=>{setError('');void loadHistory();},[loadHistory]);
 useEffect(()=>{bottom.current?.scrollIntoView({behavior:'smooth'});},[messages]);
 useEffect(()=>()=>{controller.current?.abort();if(recognition.current)recognition.current.stop();window.speechSynthesis?.cancel();},[]);
 async function send(text=question,regenerate=false){if(!text.trim()||streaming)return;setError('');setStreaming(true);setQuestion('');let assistant='';
  if(!regenerate){setMessages((m)=>[...m,{id:`local-${Date.now()}`,role:'user',content:text}]);}
  setMessages((m)=>{const next=regenerate?[...m.slice(0,Math.max(0,m.map((x)=>x.role).lastIndexOf('assistant')))]:[...m];return [...next,{id:`assistant-${Date.now()}`,role:'assistant',content:'',sources:[]}];});
  controller.current=new AbortController();
  try{
   const res=await authFetch('/assistant/stream',{method:'POST',headers:{'Content-Type':'application/json','Accept':'text/event-stream'},body:JSON.stringify({question:text,caseId,regenerate}),signal:controller.current.signal});
   if(!res.ok||!res.body){const data=await res.json().catch(()=>null);throw new Error(data?.detail||'AI model is still downloading or Ollama is unavailable.');}
   const reader=res.body.getReader(),decoder=new TextDecoder();let buffer='';
   const handle=(block:string)=>{let event='message',data='';for(const line of block.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim();}if(!data)return;const payload=JSON.parse(data);if(event==='token'){assistant+=payload.text;setMessages((m)=>{const copy=[...m];const last=copy[copy.length-1];if(last?.role==='assistant')copy[copy.length-1]={...last,content:assistant};return copy;});}if(event==='sources')setMessages((m)=>{const copy=[...m];const last=copy[copy.length-1];if(last?.role==='assistant')copy[copy.length-1]={...last,sources:payload.sources};return copy;});if(event==='error')throw new Error(payload.message);};
   while(true){const {done,value}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});let pos;while((pos=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,pos);buffer=buffer.slice(pos+2);handle(block);}if(done)break;}
   await loadHistory();
  }catch(e){if(e instanceof DOMException&&e.name==='AbortError'){setError('Response stopped.');}else{const message=e instanceof Error?e.message:'Assistant unavailable';setError(message);setMessages((m)=>m.filter((msg)=>!msg.id.startsWith('assistant-')&&!msg.id.startsWith('local-')));}}
  finally{setStreaming(false);controller.current=null;void loadHistory();}
 }
 async function clear(){if(!window.confirm('Clear chat history for this conversation?'))return;try{await jsonApi(`/assistant/history${qs}`,{method:'DELETE'});setMessages([]);setError('');}catch(e){setError(e instanceof Error?e.message:'Could not clear chat');}}
 async function regenerate(){const last=[...messages].reverse().find((m)=>m.role==='user');if(last)await send(last.content,true);}
 async function copy(text:string,id:string){try{await navigator.clipboard.writeText(text);setCopied(id);setTimeout(()=>setCopied(''),1800);}catch{setError('Clipboard access is unavailable in this browser.');}}
 function speak(text:string){if(!('speechSynthesis'in window)){setVoiceMessage('Speech playback is not supported in this browser.');return;}window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang=language==='kn'?'kn-IN':language==='hi'?'hi-IN':'en-IN';utterance.onstart=()=>setSpeaking(true);utterance.onend=()=>setSpeaking(false);utterance.onerror=()=>{setSpeaking(false);setVoiceMessage('Speech playback failed for this language.');};window.speechSynthesis.speak(utterance);}
 function stopSpeech(){window.speechSynthesis?.cancel();setSpeaking(false);}
 function startMic(){const w=window as any;const Ctor=w.SpeechRecognition||w.webkitSpeechRecognition;if(!Ctor){setVoiceMessage('Speech recognition is not supported here. Try Chrome or type your question.');return;}try{const r=new Ctor();recognition.current=r;r.lang=language==='kn'?'kn-IN':language==='hi'?'hi-IN':'en-IN';r.interimResults=true;r.onresult=(event:any)=>{const phrase=Array.from(event.results).map((x:any)=>x[0].transcript).join('');setQuestion(phrase);};r.onerror=(event:any)=>{setListening(false);setVoiceMessage(event.error==='not-allowed'?'Microphone permission was denied. Allow microphone access in browser settings.':event.error==='no-speech'?'No speech was detected. Try again.':`Voice input failed: ${event.error}.`);};r.onend=()=>setListening(false);r.start();setListening(true);setVoiceMessage('');}catch{setVoiceMessage('Microphone could not start. Check browser permission and try again.');setListening(false);}}
 function stopMic(){recognition.current?.stop();setListening(false);}
 const lastAssistant=[...messages].reverse().find((m)=>m.role==='assistant'&&m.content);
 return <section className="assistant-card chat-panel"><div className="assistant-heading"><div className="spark-icon"><BookOpen size={15}/></div><div><b>{t('Knowledge assistant')}</b><small>{caseId?t('Case assistant'):t('General assistant')}</small></div><button className="quiet-btn" title={t('Clear chat')} onClick={()=>void clear()}><Trash2 size={15}/></button></div><div className="chat-messages">{messages.length===0&&!streaming&&<div className="chat-welcome"><div className="spark-icon large"><BookOpen size={20}/></div><b>{caseId?'Ask about this case':'Ask about reviewed guidance'}</b><p>Answers use reviewed source material and include citations.</p><div className="suggestions"><button onClick={()=>void send(caseId?'Summarize the reviewed documents in this case.':'What verified sources are available?')}>Summarize relevant sources <ArrowUpRight size={12}/></button><button onClick={()=>void send('What should I verify before acting on this information?')}>What should I verify? <ArrowUpRight size={12}/></button></div></div>}{messages.map((m)=><article className={`chat-message ${m.role}`} key={m.id}><div className="message-role">{m.role==='user'?'You':'Sama AI'}</div><p>{m.content||<span className="typing-dots"><i/><i/><i/></span>}</p>{m.sources?.length? <div className="sources"><b>Sources</b>{m.sources.map((s)=><button key={s.id} onClick={()=>onOpenSource(s)}><FileText size={12}/>{s.title}<ArrowUpRight size={11}/></button>)}</div>:null}{m.role==='assistant'&&m.content&&<div className="message-actions"><button onClick={()=>void copy(m.content,m.id)}>{copied===m.id?<Check size={13}/>:<Copy size={13}/>} {copied===m.id?'Copied':t('Copy')}</button><button onClick={()=>speak(m.content)}><Volume2 size={13}/> Read aloud</button></div>}</article>)}<div ref={bottom}/></div>{error&&<div className="chat-error" role="alert">{error}</div>}{voiceMessage&&<div className="chat-error">{voiceMessage}</div>}<div className="chat-suggestions"><button onClick={()=>void send('Summarize the verified source material.')}>Summarize</button><button onClick={()=>void send('List the next checks an officer should make, with sources.')}>Next checks</button></div><form className="ask-form" onSubmit={(e)=>{e.preventDefault();void send();}}><textarea value={question} onChange={(e)=>setQuestion(e.target.value)} placeholder={t('Ask a question')+'…'} rows={1} disabled={streaming}/><button type="button" className={`mic-btn ${listening?'listening':''}`} title="Speak question" onClick={listening?stopMic:startMic}>{listening?<span className="listening-pulse"/>:<Mic size={16}/>}</button><button type="submit" disabled={!question.trim()||streaming} aria-label={t('Ask a question')}>{streaming?<span className="mini-spinner"/>:<Send size={15}/>}</button></form><div className="chat-bottom"><span><ShieldCheck size={12}/> Verify answers with the cited source.</span><div>{streaming&&<button onClick={()=>controller.current?.abort()}>Stop response</button>}{!streaming&&lastAssistant&&<button onClick={()=>void regenerate()}>{t('Regenerate')}</button>}{speaking&&<button onClick={stopSpeech}>{t('Stop speaking')}</button>}</div></div></section>;
}
